#Region @DOC
#### Description:
#Creates a backup of a Planning Analytics SaaS database, optionally waiting until it is available.
#
#### How to Use:
#
#- `pBackupFileName`: REQUIRED: the backup name, without an extension. `.tgz` is added. These characters are not allowed: `#=:|+?*,;."/\[]&<>` and backtick.
#- `pDatabaseName`: OPTIONAL: the database to back up. If blank, the database from the connection is used.
#- `pWaitForComplete`: 1 = wait until the backup appears in `}bedrock.server.backup.list`, checking every `pWaitInterval` seconds for up to `pTimeout` seconds.
#- `pRunProcessMode`: set to 1 when the connection's values in `}bedrock.session.start` are read from a cube. The session is then started with `RunProcess` and its details are read back from a file.
#- `pConnectionName`: a connection name configured in `}bedrock.session.start`, or a connection-details JSON object returned by it. When a JSON object is passed, that session is reused and is not closed at the end of this process.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#
#> [!IMPORTANT]
#> This process calls the Planning Analytics SaaS backup API (`/pakate/v0/v12db/...`) and only works on Planning Analytics SaaS. The host is taken from the connection's URL.
#
#### Return Value:
#`sBedrockReturnValue` is set to the response of the backup request, or the backup list if `pWaitForComplete = 1`.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';
cMsgErrorContent= 'User:%cUserName% Process:%cThisProcName% ErrorMsg:%sMessage%';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pConnectionName":  null,
  "pDatabaseName":  null,
  "pBackupFileName":                null,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0,
  "pWaitForComplete": 0,
  "pTimeout": 1800,
  "pWaitInterval": 15,
  "pRunProcessMode": 0
}';

pPassedParameters = '{
  "pConnectionName":  '|StringToJson  ( pConnectionName  )|',
  "pDatabaseName":  '|StringToJson  ( pDatabaseName  )|',
  "pBackupFileName":                '|StringToJson  ( pBackupFileName                )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|',
  "pWaitForComplete": '|NumberToString( pWaitForComplete )|',
  "pTimeout": '|NumberToString( pTimeout )|',
  "pWaitInterval": '|NumberToString( pWaitInterval )|',
  "pRunProcessMode": '|NumberToString( pRunProcessMode )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
pWaitForComplete = StringToNumber( JsonToString( pJson, '/pWaitForComplete' ) );
pTimeout = StringToNumber( JsonToString( pJson, '/pTimeout' ) );
pWaitInterval = StringToNumber( JsonToString( pJson, '/pWaitInterval' ) );
pRunProcessMode = StringToNumber( JsonToString( pJson, '/pRunProcessMode' ) );
# String Parameters
IF( JsonType( JsonGet( pJson, '/pConnectionName' ) ) @= 'string' );
  pConnectionName = JsonToString( pJson, '/pConnectionName' );
ELSE;
  pConnectionName = JsonGet( pJson, '/pConnectionName' );
ENDIF;
pDatabaseName  =                 JsonToString( pJson, '/pDatabaseName'  );
pBackupFileName                =                 JsonToString( pJson, '/pBackupFileName'                );
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

# Validate pBackupFileName
pBackupFileName = TRIM( pBackupFileName );

sForbiddenChars = '#=:|+?*,;."/\[]&<>`';
WHILE( LONG( sForbiddenChars ) <> 0 );
  sForbiddenChar = SUBST( sForbiddenChars, 1, 1 );
  sForbiddenChars = DELET( sForbiddenChars, 1, 1 );
  
  IF( SCAN( sForbiddenChar, pBackupFileName ) <> 0 );
    nErrors = 1;
    sMessage = 'The following characters are forbidden in pBackupFileName: [#=:|+?*,;."/\[]&<>`]'; LogOutput( 'ERROR', EXPAND( cMsgErrorContent ) );
    ProcessBreak;
  ENDIF;
END;

pBackupFileName = pBackupFileName | '.tgz';

# Get Database Connection Details
sDatabaseParameterType = JsonType( pConnectionName );
IF( sDatabaseParameterType @<> 'object' );
  IF( pRunProcessMode = 0 );
    ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pConnectionName, 'pJson', pJson ); sConnectionDetails = sBedrockReturnValue;
  ELSE;
    RunProcess( '}bedrock.session.start', 'pConnectionName', pConnectionName, 'pRunProcessMode', 1, 'pJson', pJson ); 
    ExecuteProcess( '}bedrock.file.read', 'pFile', '^'|pConnectionName|'.json', 'pTimeout', 30, 'pWaitInterval', .1 ); sConnectionDetails = sBedrockReturnValue; ASCIIDelete( '^'|pConnectionName|'.json' );
  ENDIF;
ELSE;
  sConnectionDetails = pConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pConnectionName', sConnectionDetails );

### Authentication headers for requests to this connection
sAuthHeaders = '[]';
IF( JsonToString( sConnectionDetails, '/sAuthHeader' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sConnectionDetails, '/sSID' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sConnectionDetails, '/sSID' ) ) );
ENDIF;

sConnectionURL = JsonToString( sConnectionDetails, '/sURL' );
### Planning Analytics SaaS host, taken from the connection's base URL
nHostStart  = SCAN( '://', sConnectionURL ) + 3;
nHostLength = SCAN( '/', DELET( sConnectionURL, 1, nHostStart - 1 ) ) - 1;
sHostURL    = SUBST( sConnectionURL, 1, nHostStart - 1 + nHostLength );

# Get Database Details
IF( pDatabaseName @= '' );
  pDatabaseName = JsonToString( sConnectionDetails, 'sDBN' );
ENDIF;

sURL = JsonToString( sConnectionDetails, 'sURL' );
sSID = JsonToString( sConnectionDetails, 'sSID' );

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Execute HTTP Requests

sRequestURL = sHostURL | '/pakate/v0/v12db/'|pDatabaseName|'/backup';

# Get Server Host ID
ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod', 'POST',
  'pBody', '{"url":'|StringToJson( pBackupFileName )|'}',
  'pHeaders', sAuthHeaders,
  'pURL', sRequestURL,
  'pJson', pJson );
sResponse = sBedrockReturnValue;

# Wait for the backup to complete
IF( pWaitForComplete = 1 );
  nFoundBackup = 0;
  
  # Repeatedly retrieve backup list
  WHILE( nFoundBackup = 0 & pTimeout > 0 );
    ExecuteProcess('}bedrock.server.backup.list',
      'pConnectionName', sConnectionDetails,
      'pDatabaseName', pDatabaseName,
      'pBackupType','BOTH',
      'pJson', pJson );
    sBackups = sBedrockReturnValue;
    
    WHILE( JsonSize( sBackups ) > 0 );
      sBackupName = JsonToString( sBackups, '/0/name' );
      sBackups = JsonRemove( sBackups, 0 );

      IF( sBackupName @= pBackupFileName );
        nFoundBackup = 1;
      ENDIF;
    END;
    
    SLEEP( pWaitInterval * 1000 );
    pTimeout = pTimeout -  pWaitInterval;
  END;
ENDIF;

#EndRegion - Execute HTTP Requests
#################################################################################################

