#****Begin: Generated Statements***
#****End: Generated Statements****

##################################################################################################
#Region - Cleanup

IF( nErrors <> 0 );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ENDIF;
ENDIF;

IF( sDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sURL | '/ActiveSession/tm1.Close', 'pHeaders', sAuthHeaders );
ENDIF;

#EndRegion - Cleanup
#################################################################################################
